import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TablePagination,
  TableRow,
  Tabs,
  Typography,
  useMediaQuery,
} from '@mui/material';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import { scrollableTabsSx } from '../../constants/appShellLayout';
import { useTheme } from '@mui/material/styles';
import TabSectionNavLinks from '../TabSectionNavLinks';
import {
  formatHighValueBillStatus,
  formatImportAmount,
  formatImportDate,
  formatSimilarityScore,
  calmImportLead,
  friendlyImportIssue,
  getImportCategoryCount,
  pendingRowKey,
  type ImportDetailsTab,
  type LastAccountingImportResult,
  type PendingBillUpload,
} from './accountingImportResult';
import { BILL_UPLOAD_DISABLED_MESSAGE, isBillUploadEnabled } from '../../constants/uiVisibility';

export type ImportDetailsMode = 'summary' | 'rows';

interface AccountingImportDetailsProps {
  open: boolean;
  result: LastAccountingImportResult;
  tab: ImportDetailsTab;
  mode?: ImportDetailsMode;
  uploadingSourceId?: string | null;
  onClose: () => void;
  onTabChange: (tab: ImportDetailsTab) => void;
  onReviewBillRequired: () => void;
  onUploadBill: (pending: PendingBillUpload, file: File) => void;
}

const IMPORT_PREVIEW_ROW_CAP = 50;
const PREVIEW_PAGE_SIZES = [10, 25, 50];

const idCellSx = {
  maxWidth: 220,
  wordBreak: 'break-all',
  fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
  fontSize: '0.75rem',
  lineHeight: 1.45,
};

const TAB_LABELS: Record<ImportDetailsTab, string> = {
  imported: 'Imported',
  billRequired: 'Bill required',
  duplicates: 'Duplicates',
  invalid: 'Invalid',
  failed: 'Failed',
};

const TAB_ORDER: ImportDetailsTab[] = [
  'imported',
  'billRequired',
  'duplicates',
  'invalid',
  'failed',
];

const EMPTY_COPY: Record<ImportDetailsTab, string> = {
  imported: 'No transactions were imported.',
  billRequired: 'No transactions require bill upload.',
  duplicates: 'No duplicate transactions were found in this import.',
  invalid: 'No invalid rows were detected.',
  failed: 'No transactions failed to save.',
};

const EmptyState: React.FC<{ message: string }> = ({ message }) => (
  <Box sx={{ textAlign: 'center', py: 4 }}>
    <Typography variant="body2" color="text.secondary">
      {message}
    </Typography>
  </Box>
);

const SummaryStat: React.FC<{ label: string; value: number }> = ({ label, value }) => (
  <Box sx={{ minWidth: 0 }}>
    <Typography variant="caption" color="text.secondary">{label}</Typography>
    <Typography variant="h6" component="p" sx={{ fontWeight: 700, lineHeight: 1.2 }}>
      {value.toLocaleString('en-IN')}
    </Typography>
  </Box>
);

const AccountingImportDetails: React.FC<AccountingImportDetailsProps> = ({
  open,
  result,
  tab,
  mode = 'rows',
  uploadingSourceId,
  onClose,
  onTabChange,
  onReviewBillRequired,
  onUploadBill,
}) => {
  const theme = useTheme();
  const fullScreen = useMediaQuery(theme.breakpoints.down('sm'));
  const [previewPage, setPreviewPage] = useState(0);
  const [previewRowsPerPage, setPreviewRowsPerPage] = useState(10);
  const visibleTabs = TAB_ORDER.filter((key) => key === 'imported' || getImportCategoryCount(result, key) > 0);
  const tabIndex = Math.max(0, visibleTabs.indexOf(tab));
  const tabLabels = visibleTabs.map((key) => (
    key === 'imported'
      ? `${TAB_LABELS[key]} (${getImportCategoryCount(result, key).toLocaleString('en-IN')} total)`
      : `${TAB_LABELS[key]} (${getImportCategoryCount(result, key).toLocaleString('en-IN')})`
  ));
  const loadedPreviewCount = result.imported.length;
  const importedTotal = result.totals.imported;
  const previewPageCount = Math.max(1, Math.ceil(loadedPreviewCount / previewRowsPerPage) || 1);
  const safePreviewPage = Math.min(previewPage, previewPageCount - 1);
  const previewStart = safePreviewPage * previewRowsPerPage;
  const previewRows = result.imported.slice(previewStart, previewStart + previewRowsPerPage);
  const rangeStart = loadedPreviewCount === 0 ? 0 : previewStart + 1;
  const rangeEnd = previewStart + previewRows.length;
  const formatHint = result.detection?.format || result.importMeta?.format;

  useEffect(() => {
    setPreviewPage(0);
  }, [open, result.fileName, loadedPreviewCount, tab]);

  const selectTab = (nextIndex: number) => {
    const next = visibleTabs[nextIndex];
    if (next) {
      onTabChange(next);
    }
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      fullScreen={fullScreen}
      aria-labelledby="accounting-import-details-title"
    >
      <DialogTitle id="accounting-import-details-title">
        {mode === 'summary' ? 'Import summary' : 'Import details'}
        <Typography variant="body2" color="text.secondary" sx={{ wordBreak: 'break-word' }}>
          {result.fileName}
          {result.providerLabel ? ` · ${result.providerLabel}` : ''}
        </Typography>
      </DialogTitle>
      <DialogContent dividers>
        <Tabs
          value={mode === 'summary' ? false : (tabIndex < 0 ? 0 : tabIndex)}
          onChange={(_event, nextIndex: number) => selectTab(nextIndex)}
          variant="scrollable"
          scrollButtons="auto"
          allowScrollButtonsMobile
          aria-label="Import result categories"
          sx={{ mb: 1, ...scrollableTabsSx }}
        >
          {visibleTabs.map((key, index) => (
            <Tab
              key={key}
              id={`import-details-tab-${key}`}
              aria-controls={`import-details-panel-${key}`}
              label={tabLabels[index]}
            />
          ))}
        </Tabs>
        {mode === 'rows' && (
          <TabSectionNavLinks
            tabLabels={tabLabels}
            currentIndex={tabIndex < 0 ? 0 : tabIndex}
            onNavigate={selectTab}
          />
        )}

        {mode === 'summary' ? (
          <Stack spacing={1.5} sx={{ mt: 1 }}>
            <Box>
              <Typography variant="caption" color="text.secondary">File</Typography>
              <Typography variant="body1" sx={{ fontWeight: 600, wordBreak: 'break-word' }}>
                {result.fileName}
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block">
                {[result.providerLabel, formatHint].filter(Boolean).join(' · ') || 'Connector not recorded'}
              </Typography>
            </Box>
            <Box
              sx={{
                display: 'grid',
                gap: 1,
                gridTemplateColumns: { xs: '1fr 1fr', sm: 'repeat(3, minmax(0, 1fr))' },
              }}
            >
              {result.totals.received != null && (
                <SummaryStat label="Records received" value={result.totals.received} />
              )}
              {result.totals.parsed != null && (
                <SummaryStat label="Records parsed" value={result.totals.parsed} />
              )}
              <SummaryStat label="Imported" value={importedTotal} />
              <SummaryStat label="Bill required" value={result.totals.pendingBillUpload} />
              <SummaryStat label="Duplicates" value={result.totals.duplicates} />
              <SummaryStat label="Invalid" value={result.totals.invalid} />
              <SummaryStat label="Failed" value={result.totals.persistFailures} />
            </Box>
            <Typography variant="body2">{calmImportLead(result)}</Typography>
            {result.message && !/showing the first/i.test(result.message) && (
              <Typography variant="body2" color="text.secondary">
                {result.message}
              </Typography>
            )}
            <Typography variant="caption" color="text.secondary">
              {importedTotal > loadedPreviewCount
                ? `This summary uses the import totals. The row tabs list ${loadedPreviewCount} loaded preview rows, not all ${importedTotal.toLocaleString('en-IN')} imported records.`
                : 'Choose a tab to inspect the rows loaded for this import.'}
            </Typography>
            <TabSectionNavLinks
              tabLabels={tabLabels}
              currentIndex={-1}
              onNavigate={selectTab}
              prefix="Open"
            />
          </Stack>
        ) : (
        <Box
          role="tabpanel"
          id={`import-details-panel-${tab}`}
          aria-labelledby={`import-details-tab-${tab}`}
          sx={{ mt: 1 }}
        >
          {tab === 'imported' && (
            result.imported.length === 0 ? (
              <EmptyState message={EMPTY_COPY.imported} />
            ) : (
              <>
                <Typography variant="body2" sx={{ mb: 0.5 }}>
                  {`Showing ${rangeStart.toLocaleString('en-IN')}–${rangeEnd.toLocaleString('en-IN')} of ${loadedPreviewCount.toLocaleString('en-IN')} loaded preview rows · ${importedTotal.toLocaleString('en-IN')} imported in total.`}
                </Typography>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                  {importedTotal > loadedPreviewCount
                    ? `At most ${IMPORT_PREVIEW_ROW_CAP} preview rows are loaded. Pagination only moves through those rows and does not retrieve the rest of the import. Row is the source row number from the file.`
                    : 'Row is the source row number from the file. These are the loaded preview rows for this import.'}
                </Typography>
                <ScrollableTableContainer sx={{ maxHeight: 420 }}>
                  <Table size="small" stickyHeader>
                    <TableHead>
                      <TableRow>
                        <TableCell>Row</TableCell>
                        <TableCell>Source ID</TableCell>
                        <TableCell align="right">Amount</TableCell>
                        <TableCell>Date</TableCell>
                        <TableCell>ID</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {previewRows.map((row, index) => (
                        <TableRow key={row.id || row.sourceId || `imported-${row.rowIndex ?? index}`}>
                          <TableCell sx={{ whiteSpace: 'nowrap' }}>{row.rowIndex ?? '—'}</TableCell>
                          <TableCell sx={idCellSx}>{row.sourceId || '—'}</TableCell>
                          <TableCell align="right" sx={{ whiteSpace: 'nowrap' }}>{formatImportAmount(row.amount)}</TableCell>
                          <TableCell sx={{ whiteSpace: 'nowrap' }}>{formatImportDate(row.date)}</TableCell>
                          <TableCell sx={idCellSx}>{row.id || '—'}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </ScrollableTableContainer>
                <TablePagination
                  component="div"
                  count={loadedPreviewCount}
                  page={safePreviewPage}
                  rowsPerPage={previewRowsPerPage}
                  rowsPerPageOptions={PREVIEW_PAGE_SIZES}
                  onPageChange={(_event, nextPage) => setPreviewPage(nextPage)}
                  onRowsPerPageChange={(event) => {
                    setPreviewRowsPerPage(parseInt(event.target.value, 10));
                    setPreviewPage(0);
                  }}
                  labelDisplayedRows={({ from, to, count }) => `${from}–${to} of ${count} loaded`}
                />
              </>
            )
          )}

          {tab === 'billRequired' && (
            result.pendingBillUpload.length === 0 ? (
              <EmptyState message={EMPTY_COPY.billRequired} />
            ) : (
              <Stack spacing={1.5}>
                <Alert severity={isBillUploadEnabled() ? 'info' : 'warning'}>
                  {isBillUploadEnabled()
                    ? 'These rows are saved. Upload the matching bill when you have it. Matching is not proof the document is authentic.'
                    : BILL_UPLOAD_DISABLED_MESSAGE}
                </Alert>
                {isBillUploadEnabled() ? (
                <Button
                  variant="outlined"
                  color="warning"
                  onClick={onReviewBillRequired}
                  sx={{ alignSelf: { xs: 'stretch', sm: 'flex-start' } }}
                >
                  Open bill upload dialog
                </Button>
                ) : null}
                {result.pendingBillUpload.map((pending) => {
                  const preview = pending.uploadRequest?.transactionPreview;
                  const sourceId = pending.sourceId || preview?.sourceId || `row-${pending.rowIndex}`;
                  const rowKey = pendingRowKey(pending);
                  const isUploading = uploadingSourceId === rowKey;
                  return (
                    <Box
                      key={rowKey}
                      sx={{ p: 1.5, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}
                    >
                      <Typography variant="subtitle2">
                        {preview?.description || pending.description || `Row ${pending.rowIndex}`}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        {pending.transactionId ? `Transaction ${pending.transactionId} · ` : ''}
                        Row {pending.rowIndex}
                        {sourceId ? ` · ${sourceId}` : ''}
                        {` · ${formatImportAmount(preview?.amount ?? pending.amount)}`}
                        {` · ${preview?.category || pending.category || 'other'}`}
                      </Typography>
                      <Chip
                        size="small"
                        color={pending.billStatus === 'mismatch' ? 'error' : 'warning'}
                        label={formatHighValueBillStatus(pending.billStatus)}
                        sx={{ mt: 1 }}
                      />
                      {pending.actionRequired && pending.billStatus === 'awaiting_bill' && (
                        <Chip size="small" color="warning" label="Action required" sx={{ mt: 1, ml: 1 }} />
                      )}
                      {pending.uploadRequest?.userGuidance && (
                        <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                          {pending.uploadRequest.userGuidance}
                        </Typography>
                      )}
                      {isBillUploadEnabled() ? (
                      <Button
                        size="small"
                        variant="contained"
                        component="label"
                        disabled={isUploading}
                        sx={{ mt: 1 }}
                        startIcon={isUploading ? <CircularProgress size={14} color="inherit" /> : undefined}
                      >
                        Upload PDF bill
                        <input
                          hidden
                          type="file"
                          accept="application/pdf,.pdf"
                          onChange={(event) => {
                            const file = event.target.files?.[0];
                            event.target.value = '';
                            if (file) {
                              onUploadBill(pending, file);
                            }
                          }}
                        />
                      </Button>
                      ) : null}
                    </Box>
                  );
                })}
              </Stack>
            )
          )}

          {tab === 'duplicates' && (
            result.duplicates.length === 0 ? (
              <EmptyState message={EMPTY_COPY.duplicates} />
            ) : (
              <ScrollableTableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Source ID</TableCell>
                      <TableCell>Reasons</TableCell>
                      <TableCell>Similarity</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {result.duplicates.map((row, index) => (
                      <TableRow key={row.sourceId || `duplicate-${row.rowIndex ?? index}`}>
                        <TableCell>{row.rowIndex ?? '—'}</TableCell>
                        <TableCell>{row.sourceId || '—'}</TableCell>
                        <TableCell>
                          {Array.isArray(row.reasons) && row.reasons.length > 0
                            ? row.reasons.map((reason) => friendlyImportIssue(reason)).join('; ')
                            : 'Already in the activity list'}
                        </TableCell>
                        <TableCell>{formatSimilarityScore(row.similarityScore)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollableTableContainer>
            )
          )}

          {tab === 'invalid' && (
            result.invalidRows.length === 0 ? (
              <EmptyState message={EMPTY_COPY.invalid} />
            ) : (
              <ScrollableTableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Source ID</TableCell>
                      <TableCell>Errors</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {result.invalidRows.map((row, index) => (
                      <TableRow key={row.sourceId || `invalid-${row.rowIndex ?? index}`}>
                        <TableCell>{row.rowIndex ?? '—'}</TableCell>
                        <TableCell>{row.sourceId || '—'}</TableCell>
                        <TableCell>
                          {Array.isArray(row.errors) && row.errors.length > 0
                            ? row.errors.map((error) => friendlyImportIssue(error)).join(' ')
                            : 'This row could not be read.'}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollableTableContainer>
            )
          )}

          {tab === 'failed' && (
            result.persistFailures.length === 0 ? (
              <EmptyState message={EMPTY_COPY.failed} />
            ) : (
              <ScrollableTableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Source ID</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell>Details</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {result.persistFailures.map((row, index) => (
                      <TableRow key={row.sourceId || `failed-${row.rowIndex ?? index}`}>
                        <TableCell>{row.rowIndex ?? '—'}</TableCell>
                        <TableCell>{row.sourceId || '—'}</TableCell>
                        <TableCell>Could not save</TableCell>
                        <TableCell>{friendlyImportIssue(row.error)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </ScrollableTableContainer>
            )
          )}
        </Box>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Close</Button>
      </DialogActions>
    </Dialog>
  );
};

export default AccountingImportDetails;
