import React from 'react';
import { Accordion, AccordionDetails, AccordionSummary, Chip, Grid, Typography } from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import type { Document } from '../services/documentService';

type ExtractedData = NonNullable<Document['extractedData']>;

const ENGINE_LABELS: Record<string, string> = {
  datalab: 'Datalab document AI',
  nemotron: 'NVIDIA Nemotron vision',
  easyocr: 'EasyOCR',
  tesseract: 'Tesseract'
};

const CONSUMPTION_UNITS: Array<[keyof NonNullable<ExtractedData['consumption']>, string]> = [
  ['electricity_kwh', 'kWh'],
  ['water_kl', 'kL'],
  ['lpg_kg', 'kg'],
  ['fuel_litres', 'litres'],
  ['distance_km', 'km']
];

const isNumber = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value);

const formatInr = (value: unknown): string | null =>
  isNumber(value) ? `₹${value.toLocaleString('en-IN', { maximumFractionDigits: 2 })}` : null;

export function resolveConsumption(data: ExtractedData): { quantity: number; unit: string } | null {
  if (isNumber(data.consumption_quantity)) {
    return { quantity: data.consumption_quantity, unit: data.consumption_unit || '' };
  }
  for (const [key, unit] of CONSUMPTION_UNITS) {
    const value = data.consumption?.[key];
    if (isNumber(value)) return { quantity: value, unit };
  }
  return null;
}

export function resolveEngineLabel(data: ExtractedData): string | null {
  const engine = String((data.ocr_metadata as Record<string, unknown> | undefined)?.engine || '').toLowerCase();
  if (!engine) return null;
  return ENGINE_LABELS[engine] || engine;
}

export function hasUtilityBillDetails(data?: ExtractedData | null): boolean {
  if (!data) return false;
  return Boolean(
    resolveConsumption(data)
    || data.consumer_number
    || data.billing_period_start
    || data.billing_period_end
    || isNumber(data.meter?.current_reading)
  );
}

const Field: React.FC<{ label: string; value: React.ReactNode }> = ({ label, value }) => (
  <Grid item xs={12} sm={6}>
    <Typography variant="body2" fontWeight="bold">{label}:</Typography>
    <Typography variant="body2">{value ?? 'N/A'}</Typography>
  </Grid>
);

/**
 * Utility bill activity fields (units consumed, consumer number, billing period, meter readings, charges).
 * Rendered only when the extraction carried utility data.
 */
const UtilityBillDetails: React.FC<{ extractedData?: ExtractedData | null }> = ({ extractedData }) => {
  if (!extractedData || !hasUtilityBillDetails(extractedData)) return null;
  const data = extractedData;
  const consumption = resolveConsumption(data);
  const engine = resolveEngineLabel(data);
  const period = data.billing_period_start || data.billing_period_end
    ? `${data.billing_period_start || '?'} → ${data.billing_period_end || '?'}`
    : null;
  const readings = isNumber(data.meter?.current_reading) || isNumber(data.meter?.previous_reading)
    ? `${data.meter?.previous_reading ?? '?'} → ${data.meter?.current_reading ?? '?'}`
      + (isNumber(data.meter?.multiplying_factor) && data.meter?.multiplying_factor !== 1 ? ` (MF ${data.meter?.multiplying_factor})` : '')
    : null;

  return (
    <Accordion sx={{ mt: 1 }}>
      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
        <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>Utility Bill Details</Typography>
        {engine && <Chip size="small" label={`Read by ${engine}`} sx={{ ml: 2 }} />}
      </AccordionSummary>
      <AccordionDetails>
        <Grid container spacing={2}>
          <Field
            label="Units consumed"
            value={consumption ? `${consumption.quantity.toLocaleString('en-IN')} ${consumption.unit}`.trim() : null}
          />
          <Field label="Consumer number" value={data.consumer_number || null} />
          <Field label="Billing period" value={period} />
          <Field label="Due date" value={data.due_date || null} />
          <Field label="Meter readings (previous → current)" value={readings} />
          <Field label="Meter number" value={data.meter_number || null} />
          <Field label="Energy charges" value={formatInr(data.energy_charges)} />
          <Field label="Fixed charges" value={formatInr(data.fixed_charges)} />
          <Field label="Electricity duty / tax" value={formatInr(data.electricity_duty)} />
          <Field label="Current charges" value={formatInr(data.current_charges)} />
          <Field label="Amount payable" value={formatInr(data.grand_total)} />
        </Grid>
      </AccordionDetails>
    </Accordion>
  );
};

export default UtilityBillDetails;
